draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // book
  ctx.fillStyle = 'brown';
  ctx.fillRect(W/2-50, H/2-50, 100, 100);
  ctx.strokeRect(W/2-50, H/2-50, 100, 100);

  // stick figure
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2-150, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2-130);
  ctx.lineTo(W/2, H/2-80);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2-100);
  ctx.lineTo(W/2-30, H/2-70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2-100);
  ctx.lineTo(W/2+30, H/2-70);
  ctx.stroke();

  // applying wisdom
  ctx.font = '30px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('Apply', W/2, H/2-200 + 50 * Math.sin(t));

  // lesson life
  ctx.font = '20px Arial';
  ctx.textAlign = 'left';
  ctx.textBaseline = 'top';
  ctx.fillStyle = 'black';
  ctx.fillText('Lessons for Life', W/2-50, H/2-50 + 20 * Math.sin(t));

  ctx.restore();
}
